//! Unit tests of dispatch, failures and the registries, without a model: a test plays the
//! backend with `ModelDpi::scope` and the trampoline with `call`. Trampolines generated by
//! `dpi_import!` are tested in `abi`.

use super::*;

trait Adder {
    fn add(&mut self, x: i32, y: i32) -> i32;
}

struct Plus(i32);

impl Adder for Plus {
    fn add(&mut self, x: i32, y: i32) -> i32 {
        assert!(x >= 0, "negative input {x}");
        x + y + self.0
    }
}

/// A call through the trampoline path for model `prefix`.
fn add(prefix: &'static str, x: i32, y: i32) -> i32 {
    call::<dyn Adder, _>(prefix, "add", 0, |imp| imp.add(x, y))
}

fn plus(n: i32) -> Box<dyn Adder> {
    Box::new(Plus(n))
}

/// A slot registered for a fresh simulation id, as `set_dpi` plus a first eval would make.
pub(super) fn bound<T: ?Sized + 'static>(prefix: &'static str, imp: Option<Box<T>>) -> ModelDpi {
    static NEXT: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(u32::MAX / 2);
    let sim_gen = NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    // The DUT is named after the prefix without its `V`, as generated prefixes are.
    let dut = prefix.strip_prefix('V').unwrap_or(prefix);
    let slot = registered(sim_gen, prefix);
    slot.claimed.set(true);
    slot.dut.set(dut);
    *slot.imp.borrow_mut() = imp.map(|i| Box::new(i) as Box<dyn Any>);
    let mut model = ModelDpi::new(prefix, dut);
    model.bound = Some((sim_gen, slot));
    model
}

#[test]
fn calls_reach_the_current_models_implementation() {
    let mut a = bound("Vone", Some(plus(100)));
    let mut b = bound("Vone", Some(plus(200)));
    assert_eq!(a.scope(|| add("Vone", 1, 2)), (103, None));
    assert_eq!(b.scope(|| add("Vone", 1, 2)), (203, None));
    // Nested scopes restore the outer model.
    let ((inner, outer), failure) =
        a.scope(|| (b.scope(|| add("Vone", 0, 0)).0, add("Vone", 0, 0)));
    assert_eq!((inner, outer, failure), (200, 100, None));
}

#[test]
fn a_panic_becomes_a_failure_and_later_calls_return_zero() {
    let mut a = bound("Vpanic", Some(plus(0)));
    let (results, failure) = a.scope(|| (add("Vpanic", -1, 0), add("Vpanic", 1, 1)));
    assert_eq!(
        results,
        (0, 0),
        "zero after the panic, implementation not run again"
    );
    let failure = failure.unwrap().message;
    assert!(
        failure.starts_with("DPI-C import `add` of DUT `panic` panicked: negative input -1."),
        "{failure}"
    );
    // The failure was taken; the next scope starts clean (the backend poisons the model).
    assert_eq!(a.scope(|| add("Vpanic", 1, 1)), (2, None));
}

#[test]
fn a_call_without_an_implementation_says_how_to_register_one() {
    let mut a = bound::<dyn Adder>("Vnone", None);
    let (value, failure) = a.scope(|| add("Vnone", 1, 2));
    assert_eq!(value, 0);
    let failure = failure.unwrap();
    assert_eq!(
        failure.message,
        "the design called DPI-C import `add`, but DUT `none` has no DPI implementation",
        "the problem only: the advice is the help's"
    );
    assert!(matches!(
        failure.kind,
        DpiFailureKind::Setup { help } if help.contains("dut.set_dpi(..)")
    ));
}

#[test]
fn a_call_into_another_models_trampoline_names_both() {
    let mut b = bound("Vb", Some(plus(0)));
    let (value, failure) = b.scope(|| add("Va", 1, 2));
    assert_eq!(value, 0);
    let failure = failure.unwrap().message;
    assert!(
        failure.starts_with(
            "DUT `b` called DPI-C import `add`, but the `add` linked into this binary is \
             the one generated for another model (prefix `Va`)"
        ),
        "{failure}"
    );
}

#[test]
fn a_call_outside_any_eval_returns_zero() {
    assert_eq!(add("Vorphan", 1, 2), 0);
}

#[test]
fn a_reentrant_call_returns_zero_and_leaves_the_outer_call_intact() {
    struct Reenter;
    impl Adder for Reenter {
        fn add(&mut self, x: i32, _y: i32) -> i32 {
            add("Vre", x, 0) + 7
        }
    }
    let mut a = bound("Vre", Some(Box::new(Reenter) as Box<dyn Adder>));
    assert_eq!(a.scope(|| add("Vre", 1, 0)), (7, None));
    assert_eq!(
        a.scope(|| add("Vre", 1, 0)),
        (7, None),
        "the slot is current again"
    );
}

#[test]
fn the_kernel_knows_a_call_is_running_only_during_it() {
    struct Probe;
    impl Adder for Probe {
        fn add(&mut self, _x: i32, _y: i32) -> i32 {
            assert_eq!(state::in_dpi_call(), Some("add"));
            1
        }
    }
    let mut a = bound("Vprobe", Some(Box::new(Probe) as Box<dyn Adder>));
    assert_eq!(a.scope(|| add("Vprobe", 1, 0)), (1, None));
    assert_eq!(state::in_dpi_call(), None);
}

#[test]
fn a_panic_is_marked_as_one_and_other_failures_are_not() {
    let mut a = bound("Vkind", Some(plus(0)));
    let (_, failure) = a.scope(|| add("Vkind", -1, 0));
    assert_eq!(failure.unwrap().kind, DpiFailureKind::Panic);
    let mut b = bound::<dyn Adder>("Vkind_none", None);
    let (_, failure) = b.scope(|| add("Vkind_none", 1, 0));
    assert!(matches!(
        failure.unwrap().kind,
        DpiFailureKind::Setup { help } if help.contains("dut.set_dpi(..)")
    ));
}

#[test]
fn two_models_claiming_one_import_name_panic() {
    claim("Vclaim_a", &["claimed_fn"]);
    claim("Vclaim_a", &["claimed_fn"]);
    let clash = panic::catch_unwind(|| claim("Vclaim_b", &["claimed_fn"])).unwrap_err();
    let message = panic_message(&*clash);
    assert!(
        message.starts_with(
            "DPI-C import `claimed_fn` is declared by models `Vclaim_a` and `Vclaim_b`"
        ),
        "{message}"
    );
}

#[test]
fn a_second_model_with_the_same_slot_fails_only_when_it_calls() {
    let sim_gen = u32::MAX - 7;
    let shared = registered(sim_gen, "Vtwin");
    shared.claimed.set(true);
    *shared.imp.borrow_mut() = Some(Box::new(plus(0)) as Box<dyn Any>);
    let mut twin = ModelDpi::new("Vtwin", "twin");
    // As `slot()` does inside a run, with the slot already claimed by the first model.
    let private = Slot::new("Vtwin", "twin", true);
    twin.bound = Some((sim_gen, Rc::clone(&private)));
    assert_eq!(twin.scope(|| ()), ((), None), "no call, no failure");
    let (_, failure) = twin.scope(|| add("Vtwin", 1, 1));
    assert!(
        failure.unwrap().message.contains(
            "two instances of DUT `twin` (one build, prefix `Vtwin`) run in one simulation"
        ),
    );
    drop(twin);
    assert!(
        SLOTS.with_borrow(|s| s.contains_key(&(sim_gen, "Vtwin"))),
        "dropping the twin keeps the first model's slot"
    );
}

#[test]
fn dropping_the_model_unregisters_its_slot() {
    let a = bound("Vdrop", Some(plus(0)));
    let key = a.bound.as_ref().map(|(g, _)| (*g, "Vdrop")).unwrap();
    assert!(SLOTS.with_borrow(|s| s.contains_key(&key)));
    drop(a);
    assert!(!SLOTS.with_borrow(|s| s.contains_key(&key)));
}

#[test]
fn a_panicking_payload_drop_does_not_unwind() {
    struct Bomb;
    impl Drop for Bomb {
        fn drop(&mut self) {
            panic!("payload drop");
        }
    }
    drop_payload(Box::new(Bomb));
}
